#!/usr/bin/env node
/**
 * Extracts zones linked to the cities generated by `extract-cities.mjs`.
 *
 * Only rows that have `d_ciudad` are kept, which reduces ~160k SEPOMEX rows
 * to the useful city/zone catalog. Each zone stores:
 *   - cityName / stateName (used by the seeder to resolve `city_id`)
 *   - name     <- d_asenta
 *   - slug     <- normalized d_asenta (unique per city)
 *   - postalCode <- d_codigo
 *
 * Output: ./zones.json (in this same folder).
 *
 * Usage (run after `extract-cities.mjs`):
 *   node src/common/database/data/extract-zones.mjs
 */
import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

const XML_PATH = fileURLToPath(new URL('./CPdescarga.xml', import.meta.url));
const CITIES_PATH = fileURLToPath(new URL('./cities.json', import.meta.url));
const OUTPUT_PATH = fileURLToPath(new URL('./zones.json', import.meta.url));

const XML_ENTITIES = {
  amp: '&',
  apos: "'",
  gt: '>',
  lt: '<',
  quot: '"',
};

function decodeXml(value) {
  return value.replace(/&(#x?[0-9a-f]+|[a-z]+);/gi, (match, entity) => {
    if (entity[0] === '#') {
      const isHex = entity[1]?.toLowerCase() === 'x';
      const codePoint = Number.parseInt(entity.slice(isHex ? 2 : 1), isHex ? 16 : 10);
      return Number.isNaN(codePoint) ? match : String.fromCodePoint(codePoint);
    }

    return XML_ENTITIES[entity.toLowerCase()] ?? match;
  });
}

function parseTable(tableXml) {
  const fields = {};

  for (const match of tableXml.matchAll(/<([A-Za-z0-9_]+)>([\s\S]*?)<\/\1>/g)) {
    fields[match[1]] = decodeXml(match[2]).trim();
  }

  return fields;
}

function cityKey(stateName, cityName) {
  return `${stateName}\u0000${cityName}`;
}

function zoneKey(stateName, cityName, name, postalCode) {
  return `${stateName}\u0000${cityName}\u0000${name}\u0000${postalCode}`;
}

function slugify(value) {
  return value
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

async function main() {
  console.log(`Leyendo ciudades desde ${CITIES_PATH} ...`);
  const citiesFile = JSON.parse(await readFile(CITIES_PATH, 'utf8'));
  const cityKeys = new Set(
    citiesFile.cities.map((city) => cityKey(city.stateName, city.name)),
  );

  console.log(`Ciudades disponibles: ${cityKeys.size}`);
  console.log(`Leyendo ${XML_PATH} ...`);
  const xml = await readFile(XML_PATH, 'utf8');
  const tables = xml.match(/<table[^>]*>[\s\S]*?<\/table>/g) ?? [];

  console.log(`Registros encontrados: ${tables.length}`);

  const zones = new Map();

  for (const table of tables) {
    const row = parseTable(table);
    const cityName = row.d_ciudad?.trim();
    const stateName = row.d_estado?.trim();
    const name = row.d_asenta?.trim();
    const postalCode = row.d_codigo?.trim();

    if (!cityName || !stateName || !name || !postalCode) {
      continue;
    }

    if (!cityKeys.has(cityKey(stateName, cityName))) {
      continue;
    }

    const key = zoneKey(stateName, cityName, name, postalCode);

    if (!zones.has(key)) {
      zones.set(key, {
        stateName,
        cityName,
        name,
        postalCode,
      });
    }
  }

  const ordered = [...zones.values()].sort(
    (a, b) =>
      a.stateName.localeCompare(b.stateName, 'es') ||
      a.cityName.localeCompare(b.cityName, 'es') ||
      a.name.localeCompare(b.name, 'es') ||
      a.postalCode.localeCompare(b.postalCode),
  );

  const usedSlugsByCity = new Map();
  const result = [];

  for (const zone of ordered) {
    const key = cityKey(zone.stateName, zone.cityName);
    let usedSlugs = usedSlugsByCity.get(key);

    if (!usedSlugs) {
      usedSlugs = new Set();
      usedSlugsByCity.set(key, usedSlugs);
    }

    const base = slugify(zone.name) || 'zona';
    let slug = base;

    if (usedSlugs.has(slug)) {
      // Same settlement name with a different postal code: keep both by
      // appending the CP to the slug.
      slug = `${base}-${zone.postalCode}`;
    }

    let suffix = 2;

    while (usedSlugs.has(slug)) {
      slug = `${base}-${zone.postalCode}-${suffix}`;
      suffix += 1;
    }

    usedSlugs.add(slug);
    result.push({ ...zone, slug });
  }

  const output = {
    source: 'CPdescarga.xml',
    generatedAt: new Date().toISOString(),
    total: result.length,
    zones: result,
  };

  await writeFile(OUTPUT_PATH, `${JSON.stringify(output, null, 2)}\n`, 'utf8');

  console.log(`Zonas únicas: ${result.length}`);
  console.log(`Ciudades con zonas: ${usedSlugsByCity.size}`);
  console.log(`Guardadas en ${OUTPUT_PATH}`);
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});
